  }
}

import React from 'react';

export default function InputForm({ input, setInput, onGenerate, onSample, loading, error }) {
  const set = (k) => (e) => setInput({ ...input, [k]: e.target.value });
  const canSubmit = input.company.trim() && input.topic.trim() && !loading;

  return (
    <form
      className="form"
      onSubmit={(e) => {
        e.preventDefault();
        if (canSubmit) onGenerate();
      }}
    >
      <label>
        회사명 *
        <input value={input.company} onChange={set('company')} placeholder="예: 쿼드비 (Quad.BE)" />
      </label>
      <label>
        행사/미팅 주제 *
        <input value={input.topic} onChange={set('topic')} placeholder="예: 화장품 패키징 플랫폼 MOLDWORK 관련 미팅" />
      </label>
      <div>
        <strong style={{ fontSize: 14 }}>통역 방향</strong>
        <div className="radio">
          <label><input type="radio" checked={input.direction === 'ko-en'} onChange={() => setInput({ ...input, direction: 'ko-en' })} /> 한 → 영</label>
          <label><input type="radio" checked={input.direction === 'en-ko'} onChange={() => setInput({ ...input, direction: 'en-ko' })} /> 영 → 한</label>
        </div>
      </div>
      <label>
        참고 자료 (선택) — 회사 소개서, 아젠다, 이메일 등을 붙여넣으면 훨씬 정확해져요
        <textarea value={input.reference} onChange={set('reference')} placeholder="여기에 텍스트 붙여넣기" />
      </label>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        <button type="submit" disabled={!canSubmit}>
          {loading ? '브리프 만드는 중… (30초~1분)' : '브리프 만들기'}
        </button>
        <button type="button" className="ghost" onClick={onSample} disabled={loading}>
          샘플 브리프 보기
        </button>
      </div>
      {error && <p className="error">{error}</p>}
    </form>
  );
}

import React, { useState } from 'react';

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// 용어집 플래시카드. 틀린 카드만 다음 라운드에 다시 나온다.
export default function Practice({ glossary }) {
  const [mode, setMode] = useState('en-ko'); // en-ko: 영어 보고 한국어 / ko-en: 반대
  const [deck, setDeck] = useState(() => shuffle(glossary));
  const [idx, setIdx] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const [wrong, setWrong] = useState([]);
  const [round, setRound] = useState(1);
  const [correctTotal, setCorrectTotal] = useState(0);

  function restart(newMode = mode) {
    setMode(newMode);
    setDeck(shuffle(glossary));
    setIdx(0);
    setFlipped(false);
    setWrong([]);
    setRound(1);
    setCorrectTotal(0);
  }

  function answer(isRight) {
    const card = deck[idx];
    const nextWrong = isRight ? wrong : [...wrong, card];
    if (isRight) setCorrectTotal((n) => n + 1);
    setFlipped(false);
    if (idx + 1 < deck.length) {
      setWrong(nextWrong);
      setIdx(idx + 1);
    } else {
      // 라운드 끝: 틀린 것만 모아서 다음 라운드
      setDeck(shuffle(nextWrong));
      setWrong([]);
      setIdx(0);
      setRound((r) => r + 1);
    }
  }

  const modeButtons = (
    <div className="tabs" style={{ justifyContent: 'center' }}>
      <button className={mode === 'en-ko' ? 'active' : ''} onClick={() => restart('en-ko')}>영어 → 한국어</button>
      <button className={mode === 'ko-en' ? 'active' : ''} onClick={() => restart('ko-en')}>한국어 → 영어</button>
    </div>
  );

  if (glossary.length === 0) return <div className="quiz">용어집이 비어 있어요.</div>;

  if (deck.length === 0) {
    return (
      <div className="quiz">
        {modeButtons}
        <h2>🎉 전부 맞혔어요!</h2>
        <p className="muted">{glossary.length}개 용어 · {round - 1}라운드 만에 완료</p>
        <button onClick={() => restart()}>처음부터 다시</button>
      </div>
    );
  }

  const card = deck[idx];
  const front = mode === 'en-ko' ? card.en : card.ko;
  const back = mode === 'en-ko' ? card.ko : card.en;

  return (
    <div className="quiz">
      {modeButtons}
      <p className="muted">
        {round === 1 ? '1라운드' : `${round}라운드 (틀린 것만)`} · {idx + 1} / {deck.length}
        {' · '}맞힌 누적 {correctTotal} / {glossary.length}
      </p>
      <div className="card" onClick={() => setFlipped(true)}>
        <div className="front">{front}</div>
        {flipped ? (
          <>
            <div className="back">{back}</div>
            {card.note && <div className="note">{card.note}</div>}
          </>
        ) : (
          <div className="note">소리 내어 말해 본 뒤 카드를 눌러 정답 확인</div>
        )}
      </div>
